<?php
namespace Tests\Feature;
use App\Models\Instansi;
use App\Models\KategoriInstansi;
use App\Models\Pegawai;
use App\Models\User;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\Storage;
use Tests\TestCase;
class MasterCrudTest extends TestCase {
 use RefreshDatabase;
 private function admin(): User { return User::factory()->role('admin')->create(); }
 public function test_master_routes_reject_guest_and_non_admin(): void { foreach(['/kategori-instansi','/instansi','/pegawai'] as $url){ auth()->logout(); $this->get($url)->assertRedirect('/login'); foreach(['pelaksana','monitoring'] as $role){$this->actingAs(User::factory()->role($role)->create())->get($url)->assertForbidden(); auth()->logout();}} }
 public function test_category_crud_validation_and_deactivation(): void { $admin=$this->admin(); $this->actingAs($admin)->get('/kategori-instansi')->assertOk(); $this->get('/kategori-instansi/create')->assertOk(); $response=$this->post('/kategori-instansi',['nama'=>'Kementerian Uji']); $response->assertRedirect('/kategori-instansi'); $category=KategoriInstansi::where('nama','Kementerian Uji')->firstOrFail(); $this->get("/kategori-instansi/{$category->id}/edit")->assertOk(); $this->put("/kategori-instansi/{$category->id}",['nama'=>'Kementerian Uji Baru','status_aktif'=>1])->assertRedirect('/kategori-instansi'); $this->post('/kategori-instansi',['nama'=>'Kementerian Uji Baru'])->assertSessionHasErrors('nama'); $this->post('/kategori-instansi',['nama'=>''])->assertSessionHasErrors('nama'); $this->delete("/kategori-instansi/{$category->id}")->assertRedirect(); $this->assertDatabaseHas('kategori_instansi',['id'=>$category->id,'status_aktif'=>0]); }
 public function test_institution_crud_relation_validation_and_deactivation(): void { $admin=$this->admin(); $category=KategoriInstansi::firstOrCreate(['nama'=>'Kategori Uji'],['status_aktif'=>true]); $this->actingAs($admin)->get('/instansi')->assertOk(); $this->get('/instansi/create')->assertOk(); $this->post('/instansi',['nama'=>'Instansi Uji','kategori_instansi_id'=>$category->id])->assertRedirect('/instansi'); $institution=Instansi::where('nama','Instansi Uji')->firstOrFail(); $this->get("/instansi/{$institution->id}/edit")->assertOk(); $this->get('/instansi')->assertSee($category->nama); $this->put("/instansi/{$institution->id}",['nama'=>'Instansi Baru','kategori_instansi_id'=>$category->id,'status_aktif'=>1])->assertRedirect('/instansi'); $this->post('/instansi',['nama'=>'','kategori_instansi_id'=>999999])->assertSessionHasErrors(['nama','kategori_instansi_id']); $this->delete("/instansi/{$institution->id}"); $this->assertDatabaseHas('instansi',['id'=>$institution->id,'status_aktif'=>0,'kategori_instansi_id'=>$category->id]); $this->assertTrue($institution->fresh()->kategoriInstansi->is($category)); }
 public function test_employee_crud_nip_and_photo_validation(): void { Storage::fake('public'); $admin=$this->admin(); $this->actingAs($admin)->get('/pegawai')->assertOk(); $this->get('/pegawai/create')->assertOk(); $this->post('/pegawai',['nama_lengkap'=>'Pegawai Uji','nip'=>'NIP-UJI','foto'=>UploadedFile::fake()->image('foto.jpg')])->assertRedirect('/pegawai'); $employee=Pegawai::where('nip','NIP-UJI')->firstOrFail(); Storage::disk('public')->assertExists($employee->foto); $this->get("/pegawai/{$employee->id}/edit")->assertOk(); $this->put("/pegawai/{$employee->id}",['nama_lengkap'=>'Pegawai Edit','nip'=>'NIP-UJI','status_aktif'=>1])->assertRedirect('/pegawai'); $this->post('/pegawai',['nama_lengkap'=>'Duplikat','nip'=>'NIP-UJI'])->assertSessionHasErrors('nip'); $this->post('/pegawai',['nama_lengkap'=>'Kosong'])->assertRedirect('/pegawai'); $this->post('/pegawai',['nama_lengkap'=>'Teks','nip'=>'NIP-TEXT','foto'=>UploadedFile::fake()->create('note.txt',10,'text/plain')])->assertSessionHasErrors('foto'); $this->post('/pegawai',['nama_lengkap'=>'Besar','nip'=>'NIP-BESAR','foto'=>UploadedFile::fake()->create('big.jpg',2049,'image/jpeg')])->assertSessionHasErrors('foto'); $this->delete("/pegawai/{$employee->id}")->assertRedirect(); $this->assertDatabaseHas('pegawai',['id'=>$employee->id,'status_aktif'=>0]); }
}
